'use strict';
/* 픽스처 — `tools/가드계수.js` 의 `축표` 에서 **✓ 라고 적힌 칸이 실물인지** 못박는 재료다.
 * 돌아가지 않는다(파일명에 `.test.js` 를 안 붙인 것도 그래서다 — 붙이면 러너가 실행하려 든다).
 *
 * 🔑 왜 공용 픽스처(`fixtures/가드계수/`)를 안 쓰고 따로 두나 — 두 가지다:
 *   ① 그 픽스처에는 **함수식 모양이 없다**(화살표·함수선언·식 셋뿐). 표는 ㉡사본의 함수식을
 *      ✓ 로 적는데 그걸 재는 재료가 어디에도 없었다 — 표가 프로즈로 사는 자리가 딱 이런 곳이다.
 *   ② 그 픽스처의 숫자는 `tests/소스검사통로.test.js` 가 못박고 있다. 남의 못을 흔들면
 *      내 회귀가 남의 회귀를 깨는 모양이 되고, 그건 이 장치가 막으려는 병과 같은 뿌리다. */

const fs = require('fs');
const assert = require('assert');

const 소스 = fs.readFileSync('없는파일.js', 'utf8');

/* ── ㉡사본 — 표가 네 모양을 **전부 ✓** 로 적었다. 넷 다 사본 목록에 서야 한다. ────────── */

// ① 화살표
const 화살표사본 = (s) => s.replace(/\/\*[\s\S]*?\*\//g, ' ');

// ② 함수식 — 표는 ✓ 인데 공용 픽스처에 이 모양이 없어 아무도 안 재던 칸이다
const 함수식사본 = function (s) { return s.replace(/(^|[^:])\/\/[^\n]*/g, '$1'); };

// ③ 함수 선언 (08-13 2차에 ㉡이 배운 모양)
function 선언사본(s) { return s.replace(/\/\*[\s\S]*?\*\//g, ' '); }

// ④ 식 — 함수가 아니라 «값»이다 (2차)
const 식사본 = 소스.replace(/\/\*[\s\S]*?\*\//g, ' ');

/* ── ㉠원문생산자 — 표가 함수선언을 ✓ 로 적은 칸. 08-14 **4차**가 난 바로 그 자리다. ─────
 * ⚠ 이름을 `구간`·`코드만` 으로 지으면 안 된다 — 그 둘은 이 저장소의 **공용 정제 통로 이름**이라
 *   계수기가 무조건 정제로 흡수한다(첫 판이 그 이름을 써서 위험 0 이 나왔다 · 실측 08-14).
 * `원문조각()` 은 원문(`소스`)의 파생을 내주므로 «원문 생산자»로 서야 하고, 그것을 정제 없이
 * 재는 아래 단언은 **위험**으로 서야 한다. 이 칸이 ✗ 로 돌아가면(=옛 사각이 되살아나면)
 * 이 자리는 위험이 아니라 ❔모름으로 새고, 새는 방향은 언제나 「좋아 보인다」다. */
function 원문조각(a, b) { return 소스.slice(a, b); }

assert.ok(!원문조각(0, 10).includes('평균'));

module.exports = { 화살표사본, 함수식사본, 선언사본, 식사본, 원문조각 };
